<template>
  <AppPageHeader :height="dashboard && mobile ? 120 : 56" class="dashboard-appbar">
    <div class="dashboard-topbar">
      <div class="dashboard-breadcrumb"><v-icon icon="mdi-view-dashboard-outline" size="19"/><router-link to="/dashboard" :aria-label="t(&quot;Back to dashboards&quot;)">{{ dashboard ? dashboard.folder : t('Dashboards') }}</router-link><template v-if="dashboard"><span>/</span><span class="dashboard-name">{{ dashboard.name }}</span><span v-if="dirty" class="unsaved-dot" :aria-label="t(&quot;Unsaved changes&quot;)" :title="t(&quot;Unsaved changes&quot;)" /></template></div>
      <div v-if="dashboard" class="dashboard-controls">
        <v-btn v-if="canManage" icon="mdi-chart-box-plus-outline" variant="outlined" :aria-label="t(&quot;Add panel&quot;)" :title="t(&quot;Add panel&quot;)" @click="openEditor()"/>
        <v-btn v-if="canManage" icon="mdi-content-save-outline" variant="outlined" :color="dirty?'primary':undefined" :disabled="!dirty" :loading="saving" :aria-label="t(&quot;Save dashboard&quot;)" :title="t(&quot;Save dashboard&quot;)" @click="save"/>
        <v-btn v-if="canManage" icon="mdi-cog-outline" variant="outlined" :aria-label="t(&quot;Dashboard settings&quot;)" :title="t(&quot;Dashboard settings&quot;)" @click="openSettings"/>
        <DashboardTimeRange v-if="!settingsFor(dashboard).hideTimePicker" v-model="range" :timezone="settingsFor(dashboard).timezone"/>
        <v-btn icon="mdi-magnify-minus-outline" variant="outlined" :aria-label="t(&quot;Zoom out time range&quot;)" :title="t(&quot;Zoom out time range&quot;)" @click="zoomOut"/>
        <div class="refresh-controls"><v-btn icon="mdi-refresh" variant="outlined" :aria-label="t(&quot;Refresh panels&quot;)" :title="t(&quot;Refresh panels&quot;)" :disabled="fetching" @click="refreshData"/><select v-model="refresh" :aria-label="t(&quot;Auto refresh&quot;)"><option v-for="value in ['Off',...settingsFor(dashboard).intervals]" :key="value" :value="value">{{ t(value) }}</option></select></div>
        <v-btn icon="mdi-monitor" variant="outlined" :aria-label="t(&quot;Toggle browser full screen&quot;)" :title="t(&quot;Full screen&quot;)" @click="toggleFullscreen"/>
        <v-menu><template #activator="{props}"><v-btn v-bind="props" icon="mdi-dots-vertical" variant="outlined" :aria-label="t(&quot;More dashboard actions&quot;)" :title="t(&quot;More dashboard actions&quot;)"/></template><v-list density="compact"><v-list-item v-if="canManage" :title="t(&quot;Data explorer&quot;)" prepend-icon="mdi-database-search" @click="openEditor()"/><v-list-item :title="t(&quot;Export charts&quot;)" prepend-icon="mdi-export" @click="exportCurrent"/><v-list-item v-if="canManage" :title="t(&quot;Duplicate&quot;)" prepend-icon="mdi-content-copy" @click="duplicate"/><v-list-item v-if="canManage" :title="t(&quot;Discard changes&quot;)" prepend-icon="mdi-undo" :disabled="!dirty" @click="dialog={kind:'discard'}"/></v-list></v-menu>
      </div>
    </div>
  </AppPageHeader>
  <section class="app-page dashboards-page" :class="{'dashboard-canvas':dashboard}">
    <v-alert v-if="error" type="error" variant="tonal" closable class="mb-5" @click:close="error=''">{{ t(error) }}</v-alert>
    <v-alert v-if="notice" type="success" variant="tonal" closable class="mb-5" @click:close="notice=''">{{ t(notice) }}</v-alert>
    <div v-if="loading" class="app-loading-state"><v-progress-circular indeterminate color="secondary"/><p>{{ t("Loading dashboards…") }}</p></div>
    <template v-else-if="!route.params.dashboardId">
      <header class="app-page-heading"><div><h1>{{ t("Dashboards") }}</h1><p>{{ t("Keep server health and growing systems in their own dashboards.") }}</p></div><div class="app-action-row"><v-btn variant="outlined" prepend-icon="mdi-refresh" @click="load">{{ t("Refresh") }}</v-btn><v-btn v-if="canManage" variant="outlined" prepend-icon="mdi-import" @click="importInput.click()">{{ t("Import charts") }}</v-btn><v-btn v-if="canManage" prepend-icon="mdi-view-grid-plus" color="primary" @click="createDashboard">{{ t("New dashboard") }}</v-btn></div></header>
      <div class="library-filters"><v-text-field v-model="search" :label="t(&quot;Search dashboards, descriptions or tags&quot;)" prepend-inner-icon="mdi-magnify" variant="outlined" hide-details clearable/><v-select v-model="folder" :items="[{title:t('All folders'),value:'All folders'},...folders.map(value=>({title:value,value}))]" :label="t(&quot;Folder&quot;)" variant="outlined" hide-details/></div>
      <v-tabs :model-value="favorites?'starred':'all'" color="primary" class="library-tabs" @update:model-value="favorites=$event==='starred'"><v-tab value="all">{{ t("All dashboards") }}</v-tab><v-tab value="starred" prepend-icon="mdi-star-outline">{{ t("Starred") }}</v-tab></v-tabs>
      <div class="library-summary"><span>{{ t(filtered.length===1 ? '{count} dashboard' : '{count} dashboards', {count:filtered.length}) }}</span><span>{{ t("Tomatoes workspace") }}</span></div>
      <div class="library-list app-panel"><v-table class="dashboard-library"><thead><tr><th :aria-label="t(&quot;Starred&quot;)"/><th>{{ t("Dashboard") }}</th><th>{{ t("Folder") }}</th><th>{{ t("Panels") }}</th><th>{{ t("Updated") }}</th><th :aria-label="t(&quot;Actions&quot;)"/></tr></thead><tbody><tr v-for="item in filtered" :key="item._id"><td><v-btn :icon="item.favorite?'mdi-star':'mdi-star-outline'" :color="item.favorite?'warning':undefined" variant="text" :aria-label="t('Favorite {name}',{name:item.name})" :disabled="!canManage" @click="toggleFavorite(item)"/></td><td><router-link :to="`/dashboard/${item._id}`" class="library-name"><strong>{{ item.name }}</strong><span>{{ item.description || t('No description') }}</span></router-link></td><td><span class="folder-label"><v-icon icon="mdi-folder-outline" size="16"/> {{ item.folder }}</span></td><td><span class="mobile-column-label">{{ t("Panels:") }} </span>{{ item.panelCount ?? '—' }}</td><td class="updated-column">{{ formatDateTime(item.updatedAt) }}</td><td><div class="app-action-row"><v-btn :to="`/dashboard/${item._id}`" variant="text" size="small">{{ t("Open") }}</v-btn><v-menu v-if="canManage"><template #activator="{props}"><v-btn v-bind="props" icon="mdi-dots-vertical" variant="text" size="small" :aria-label="t('Actions for {name}',{name:item.name})"/></template><v-list density="compact"><v-list-item :title="t(&quot;Delete dashboard&quot;)" prepend-icon="mdi-trash-can-outline" @click="dialog={kind:'delete-dashboard',item}"/></v-list></v-menu></div></td></tr></tbody></v-table><div v-if="!filtered.length" class="app-empty-state"><h2>{{ t(favorites?'No starred dashboards':'No dashboards found') }}</h2><p>{{ t(favorites?'Star a dashboard to find it here.':'Create a dashboard or import your chart JSON.') }}</p><v-btn v-if="canManage && !favorites" color="primary" prepend-icon="mdi-view-grid-plus" @click="createDashboard">{{ t("New dashboard") }}</v-btn></div></div>
    </template>
    <template v-else-if="dashboard">
      <div v-if="!dashboard.charts.length" class="app-empty-state app-panel"><h2>{{ t("Start with your first panel") }}</h2><p>{{ t("Browse available measurements or enter your Flux query.") }}</p><v-btn v-if="canManage" color="primary" prepend-icon="mdi-plus" @click="openEditor()">{{ t("Add panel") }}</v-btn></div>
      <grid-layout v-else-if="!mobile" :layout="layout" :col-num="12" :row-height="26" :margin="[8,8]" :is-draggable="canManage" :is-resizable="canManage" :vertical-compact="true" @update:layout="updateLayout" @layout-updated="updateLayout"><grid-item v-for="item in layout" :key="item.i" v-bind="item" :min-w="3" :min-h="8" drag-allow-from=".chart-header" drag-ignore-from="button,.v-btn" @move="layoutGesture=true" @resize="layoutGesture=true"><DashboardPanel :chart="chartById(item.i)" :result="results[item.i]" :editing="canManage && editing" :timezone="settingsFor(dashboard).timezone" @inspect="openInspector(chartById(item.i))" @view="focused=item.i" @edit="openEditor(chartById(item.i))" @remove="confirmRemove(chartById(item.i))" @move="moveEarlier(item.i)"/></grid-item></grid-layout>
      <div v-else class="mobile-panels"><DashboardPanel v-for="chart in sortedCharts" :key="chart.id" :chart="chart" :result="results[String(chart.id)]" :editing="canManage && editing" :timezone="settingsFor(dashboard).timezone" @inspect="openInspector(chart)" @view="focused=String(chart.id)" @edit="openEditor(chart)" @remove="confirmRemove(chart)" @move="moveEarlier(String(chart.id))"/></div>
    </template>
    <div v-else class="app-empty-state"><h2>{{ t("Dashboard unavailable") }}</h2><v-btn @click="router.push('/dashboard')">{{ t("Back to dashboards") }}</v-btn></div>
    <input ref="importInput" hidden type="file" accept="application/json,.json" @change="importCharts">
  </section>
  <v-dialog :model-value="!!focusedChart" fullscreen :aria-label="focusedChart ? t('View panel: {name}',{name:focusedChart.options.chartTitle}) : t('View panel')" @update:model-value="!$event && (focused=null)">
    <v-card v-if="focusedChart" class="focused-chart">
      <header class="focused-toolbar">
        <div class="focused-location"><v-btn icon="mdi-arrow-left" variant="text" size="small" class="focused-back" :aria-label="t(&quot;Back to dashboard&quot;)" :title="t(&quot;Back to dashboard&quot;)" @click="focused=null"/><span class="focused-dashboard-label" :title="dashboard.folder+' / '+dashboard.name">{{ dashboard.folder }} / {{ dashboard.name }}</span><span v-if="dirty" class="unsaved-dot" :aria-label="t(&quot;Unsaved changes&quot;)"/></div>
        <div class="dashboard-controls">
          <v-btn v-if="canManage && dirty" icon="mdi-content-save-outline" variant="outlined" color="primary" :loading="saving" :aria-label="t(&quot;Save dashboard&quot;)" :title="t(&quot;Save dashboard&quot;)" @click="save"/>
          <v-btn v-if="canManage" icon="mdi-cog-outline" variant="outlined" :aria-label="t(&quot;Edit panel&quot;)" :title="t(&quot;Panel settings&quot;)" @click="openEditor(focusedChart)"/>
          <DashboardTimeRange v-if="!settingsFor(dashboard).hideTimePicker" v-model="range" :timezone="settingsFor(dashboard).timezone"/>
          <v-btn icon="mdi-magnify-minus-outline" variant="outlined" :aria-label="t(&quot;Zoom out time range&quot;)" :title="t(&quot;Zoom out time range&quot;)" @click="zoomOut"/>
          <div class="refresh-controls"><v-btn icon="mdi-refresh" variant="outlined" :aria-label="t(&quot;Refresh panel&quot;)" :title="t(&quot;Refresh panel&quot;)" :disabled="fetching" @click="refreshData"/><select v-model="refresh" :aria-label="t(&quot;Auto refresh&quot;)"><option v-for="value in ['Off',...settingsFor(dashboard).intervals]" :key="value" :value="value">{{ t(value) }}</option></select></div>
          <v-btn icon="mdi-monitor" variant="outlined" :aria-label="t(&quot;Toggle browser full screen&quot;)" :title="t(&quot;Full screen&quot;)" @click="toggleFullscreen"/>
        </div>
      </header>
      <v-alert v-if="error" type="error" variant="tonal" class="focused-error" role="alert">{{ t(error) }}</v-alert>
      <div class="focused-chart-content"><DashboardPanel :editing="canManage && editing" :chart="focusedChart" :result="results[focused]" :timezone="settingsFor(dashboard).timezone" @inspect="openInspector(focusedChart)" @view="undefined" @edit="openEditor(focusedChart)" @remove="confirmRemove(focusedChart)"/></div>
    </v-card>
  </v-dialog>
  <PanelInspector v-if="inspection" :snapshot="inspection" @close="inspection=null"/>
  <PanelEditor v-if="editor" :chart="editor.chart" :is-new="editor.isNew" :bucket="settingsFor(dashboard).bucket" :range="range" :window="currentWindow" :timezone="settingsFor(dashboard).timezone" @close="editor=null" @apply="applyPanel"/>
  <v-dialog v-model="settingsOpen" max-width="1040" scrollable><v-card v-if="settingsDraft"><v-card-title>{{ t("Dashboard settings") }}</v-card-title><v-card-text><div class="settings-layout"><nav><v-btn v-for="name in ['General','Time options','Data defaults','JSON model']" :key="name" :variant="settingsTab===name?'tonal':'text'" @click="settingsTab=name">{{ t(name) }}</v-btn></nav><div class="settings-fields"><template v-if="settingsTab==='General'"><label>{{ t("Name") }}<input v-model="settingsDraft.name" maxlength="160"></label><label>{{ t("Description") }}<textarea v-model="settingsDraft.description" rows="3" maxlength="2000"/></label><label>{{ t("Folder") }}<input v-model="settingsDraft.folder" maxlength="100" list="dashboard-folders"><datalist id="dashboard-folders"><option v-for="name in folders" :key="name">{{ name }}</option></datalist></label><label>{{ t("Tags, separated by commas") }}<input v-model="tagText"></label></template><template v-else-if="settingsTab==='Time options'"><label>{{ t("Timezone") }}<select v-model="settingsDraft.settings.timezone"><option value="Browser">{{ t("Browser") }}</option><option>UTC</option><option>America/Sao_Paulo</option></select></label><label>{{ t("Default time range") }}<select v-model="settingsDraft.settings.range"><option v-for="[name,value] in timeRanges" :key="value" :value="value">{{ t(name) }}</option></select></label><label>{{ t("Default auto refresh") }}<select v-model="settingsDraft.settings.refresh" :aria-label="t(&quot;Default auto refresh&quot;)"><option v-for="value in refreshIntervals" :key="value" :value="value">{{ t(value) }}</option></select></label><label>{{ t("Available refresh intervals, separated by commas") }}<input v-model="intervalText"></label><label class="check"><input v-model="settingsDraft.settings.hideTimePicker" type="checkbox"> {{ t("Hide time picker") }}</label><label class="check"><input v-model="settingsDraft.settings.pauseHidden" type="checkbox"> {{ t("Pause refresh when this browser tab is hidden") }}</label></template><template v-else-if="settingsTab==='Data defaults'"><label>{{ t("Default bucket") }}<input v-model="settingsDraft.settings.bucket"></label><p class="muted">{{ t("Used for new panels. Existing Flux queries keep their own bucket and tag filters.") }}</p></template><pre v-else>{{ JSON.stringify(settingsDraft,null,2) }}</pre></div></div><v-alert v-if="settingsError" type="error" variant="tonal" class="mt-4">{{ t(settingsError) }}</v-alert></v-card-text><v-card-actions><v-spacer/><v-btn @click="settingsOpen=false">{{ t("Cancel") }}</v-btn><v-btn color="primary" variant="flat" @click="applySettings">{{ t("Apply settings") }}</v-btn></v-card-actions></v-card></v-dialog>
  <v-dialog :model-value="!!dialog" max-width="520" persistent><v-card v-if="dialog"><v-card-title>{{ t(dialogTitle) }}</v-card-title><v-card-text><template v-if="dialog.kind==='remove'">{{ t('Remove {name} from this dashboard? Measurements in InfluxDB stay unchanged. Save dashboard to keep the change.',{name:dialog.chart.options.chartTitle}) }}</template><template v-else-if="dialog.kind==='delete-dashboard'">{{ t('Delete {name} and its panel definitions? Measurements in InfluxDB stay unchanged. This cannot be undone.',{name:dialog.item.name}) }}</template><template v-else-if="dialog.kind==='new'"><label class="new-name">{{ t("Dashboard name") }}<input v-model="newName" maxlength="160" @keydown.enter="confirmDialog"></label></template><template v-else>{{ t("Discard unsaved changes? You can export your draft before leaving.") }}</template></v-card-text><v-card-actions><v-spacer/><v-btn @click="cancelDialog">{{ t("Cancel") }}</v-btn><v-btn v-if="dialog.kind==='leave'" variant="outlined" @click="exportCurrent">{{ t("Export draft") }}</v-btn><v-btn color="primary" variant="flat" :loading="saving" @click="confirmDialog">{{ t(dialog.kind==='new'?'Create dashboard':dialog.kind==='remove'?'Remove panel':dialog.kind==='delete-dashboard'?'Delete dashboard':'Discard changes') }}</v-btn></v-card-actions></v-card></v-dialog>
</template>
<script setup>
import { useLanguage } from '@/composables/useLanguage';
const {t} = useLanguage();
import Authentication from '@/services/auth';
const canManage = Boolean(Authentication.currentUser?.isAdmin);
import { formatDateTime } from '@/composables/dateTime.mjs';
import AppPageHeader from '@/components/navigation/AppPageHeader.vue';
import { ref,computed,watch,onMounted,onBeforeUnmount,nextTick } from 'vue';
import { useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate } from 'vue-router';
import { GridLayout,GridItem } from 'grid-layout-plus';
import { useDisplay } from 'vuetify';
import api from '@/services/dashboardDataService';
import { http } from '@/services/http-common';
import DashboardPanel from './DashboardPanel.vue';
import PanelEditor from './PanelEditor.vue';
import PanelInspector from './PanelInspector.vue';
import DashboardTimeRange from './DashboardTimeRange.vue';
import { rangeBounds, rangeWindow } from '@/composables/dashboardTimeRange.mjs';
import { clone,settingsFor,processingFor,chartDefinition,newChart,refreshIntervals,timeRanges,resolveQuery,alignRows,downloadJson } from '@/composables/dashboardUtils.mjs';
const route=useRoute(),router=useRouter(),display=useDisplay(),mobile=computed(()=>display.width.value<760);
const inspection=ref(null);
const library=ref([]),dashboard=ref(null),saved=ref(null),loading=ref(false),saving=ref(false),editing=ref(true),dirty=ref(false),layoutGesture=ref(false),error=ref(''),notice=ref(''),search=ref(''),folder=ref('All folders'),favorites=ref(false),results=ref({}),layout=ref([]),range=ref('-1h'),refresh=ref('Off'),focused=ref(null),editor=ref(null),dialog=ref(null),newName=ref(''),importInput=ref(null),fetching=ref(false),settingsOpen=ref(false),settingsDraft=ref(null),settingsTab=ref('General'),settingsError=ref(''),tagText=ref(''),intervalText=ref('');
let timer,loadSerial=0,fetchSerial=0,leaveResolve,controllers=[],isAlive=true;
const folders=computed(()=>[...new Set(library.value.map(d=>d.folder))].sort());
const filtered=computed(()=>library.value.filter(d=>(folder.value==='All folders'||d.folder===folder.value)&&(!favorites.value||d.favorite)&&[d.name,d.description,d.folder,...d.tags].join(' ').toLowerCase().includes((search.value||'').toLowerCase())));
const focusedChart=computed(()=>dashboard.value?.charts.find(c=>String(c.id)===focused.value));
const sortedCharts=computed(()=>[...(dashboard.value?.charts||[])].sort((a,b)=>a.layout.y-b.layout.y||a.layout.x-b.layout.x));
const currentWindow=computed(()=>timeRanges.find(([,value])=>value===range.value)?.[2]||rangeWindow(range.value,settingsFor(dashboard.value).timezone));
const dialogTitle=computed(()=>({'remove':'Remove panel?','delete-dashboard':'Delete dashboard?','discard':'Discard changes?','leave':'Unsaved changes','new':'New dashboard'}[dialog.value?.kind]||''));
const message=e=>e.response?.data?.message||'The operation failed. Your draft has been kept. Please try again.';
function chartById(id){return dashboard.value.charts.find(c=>String(c.id)===id);}
function resetLayout(){layoutGesture.value=false;layout.value=dashboard.value.charts.map(c=>({...clone(c.layout),i:String(c.id)}));}
function abortQueries(){fetchSerial++;controllers.forEach(c=>c.abort());controllers=[];fetching.value=false;}
async function load(){const serial=++loadSerial;abortQueries();loading.value=true;error.value='';editor.value=null;focused.value=null;inspection.value=null;try{if(route.params.dashboardId){const {data}=await api.get(route.params.dashboardId);if(serial!==loadSerial)return;dashboard.value=data;saved.value=clone(data);range.value=settingsFor(data).range;refresh.value=settingsFor(data).refresh;editing.value=true;dirty.value=false;results.value={};resetLayout();if(route.query.panel)focused.value=String(route.query.panel);if(canManage && route.query.edit){const chart=chartById(String(route.query.edit));if(chart)openEditor(chart);}await nextTick();refreshData();}else{const {data}=await api.list();if(serial!==loadSerial)return;library.value=data;dashboard.value=null;dirty.value=false;refresh.value='Off';}}catch(e){if(serial===loadSerial){error.value=message(e);dashboard.value=null;}}finally{if(serial===loadSerial)loading.value=false;}}
async function refreshData(){
 if(!dashboard.value||fetching.value||!isAlive)return;
 const serial=++fetchSerial;fetching.value=true;
 const charts=clone(dashboard.value.charts),queryRange=clone(range.value),window=currentWindow.value,queryTimezone=settingsFor(dashboard.value).timezone,queryNow=Date.now(),bounds=rangeBounds(queryRange,queryTimezone,queryNow),rangeDescription=typeof queryRange==='string'?queryRange:bounds.label;let index=0;
 const worker=async()=>{while(index<charts.length&&serial===fetchSerial){
  const chart=charts[index++],id=String(chart.id),controller=new AbortController(),started=performance.now();let resolvedQuery='';
  controllers.push(controller);results.value[id]={...results.value[id],loading:true,error:''};
  try{
   if(!chart.query.trim())throw new Error('No query configured.');
   resolvedQuery=resolveQuery(chart.query,queryRange,window,queryTimezone,queryNow);
   const queryPath = chart.liveSource ? '/dashboards/live' : canManage ? '/influx' : '/influx/panel';
   const queryBody = chart.liveSource ? {dashboardId:dashboard.value._id,panelId:id} : canManage ? { query: resolvedQuery } : { dashboardId: dashboard.value._id, panelId: id, start: bounds.start, stop: bounds.stop, window };
   const {data}=await http.post(queryPath,queryBody,{signal:controller.signal,timeout:30000});
   const durationMs=Math.round(performance.now()-started),aligned=alignRows(data,processingFor(chart));
   if(serial===fetchSerial)results.value[id]={...aligned,rawRows:data,resolvedQuery,queryRange:rangeDescription,rangeStart:data[0]?._start||bounds.startISO,rangeStop:data[0]?._stop||bounds.stopISO,queryWindow:window,durationMs,responseBytes:new TextEncoder().encode(JSON.stringify(data)).length,loading:false,updated:Date.now(),error:data.length&&!aligned.data.slice(1).some(values=>values.some(v=>v!==null))?'The query returned no numeric values. Check the field type.':''};
  }catch(e){if(serial===fetchSerial&&e.code!=='ERR_CANCELED')results.value[id]={...results.value[id],loading:false,lastAttempt:{query:resolvedQuery,range:rangeDescription,window,durationMs:Math.round(performance.now()-started),at:new Date().toISOString()},error:chart.liveSource?(e.response?.data?.message||'Could not load live board observations.'):e.message?.includes('30 series')?e.message:'Could not query InfluxDB. Check the query and connection.'};}
  finally{controllers=controllers.filter(c=>c!==controller);}
 }};
 try{await Promise.all(Array.from({length:Math.min(3,charts.length)},worker));}finally{if(serial===fetchSerial)fetching.value=false;}
}
function openInspector(chart){inspection.value={chart:clone(chart),result:clone(results.value[String(chart.id)]||{}),dashboardName:dashboard.value.name,timezone:settingsFor(dashboard.value).timezone,range:typeof range.value==='string'?range.value:rangeBounds(range.value,settingsFor(dashboard.value).timezone).label,capturedAt:Date.now()};}

function markDirty(){editing.value=true;dirty.value=true;}
function updateLayout(next){if(!editing.value||!dashboard.value||!layoutGesture.value)return;layoutGesture.value=false;let changed=false;for(const item of next){const chart=chartById(String(item.i));if(chart&&['x','y','w','h'].some(k=>chart.layout[k]!==item[k])){chart.layout={...chart.layout,x:item.x,y:item.y,w:item.w,h:item.h,i:String(chart.id)};changed=true;}}if(changed){layout.value=next.map(item=>({...item}));dirty.value=true;}}
function moveEarlier(id){const sorted=sortedCharts.value,index=sorted.findIndex(c=>String(c.id)===id);if(index<1)return;[sorted[index-1],sorted[index]]=[sorted[index],sorted[index-1]];let x=0,y=0,rowHeight=0;sorted.forEach(chart=>{if(x+chart.layout.w>12){y+=rowHeight;x=0;rowHeight=0;}chart.layout.x=x;chart.layout.y=y;x+=chart.layout.w;rowHeight=Math.max(rowHeight,chart.layout.h);});resetLayout();markDirty();}
function zoomOut(){try{if(typeof range.value==='string'){const index=timeRanges.findIndex(([,value])=>value===range.value);range.value=timeRanges[Math.min(index+1,timeRanges.length-1)][1];}else{const bounds=rangeBounds(range.value,settingsFor(dashboard.value).timezone),padding=(bounds.stopMs-bounds.startMs)/2,candidate={from:new Date(bounds.startMs-padding).toISOString(),to:new Date(bounds.stopMs+padding).toISOString()};rangeBounds(candidate,settingsFor(dashboard.value).timezone);range.value=candidate;}}catch(issue){error.value=issue.message;}}
async function toggleFullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{error.value='Full screen is unavailable in this browser.';}}
function openEditor(chart){if(!canManage)return;editor.value={chart:chart?clone(chart):newChart(dashboard.value.charts),isNew:!chart};}
function applyPanel(chart){abortQueries();const index=dashboard.value.charts.findIndex(c=>String(c.id)===String(chart.id));if(index<0)dashboard.value.charts.push(chart);else dashboard.value.charts[index]=chart;markDirty();resetLayout();editor.value=null;refreshData();}
function confirmRemove(chart){dialog.value={kind:'remove',chart};}
async function save(){if(saving.value)return;saving.value=true;error.value='';try{const payload={...clone(dashboard.value),charts:dashboard.value.charts.map(chartDefinition)};const {data}=await api.save(payload);if(!isAlive)return;const unchanged=JSON.stringify({...clone(dashboard.value),charts:dashboard.value.charts.map(chartDefinition)})===JSON.stringify(payload);saved.value=clone(data);if(unchanged){dashboard.value=data;dirty.value=false;editing.value=true;notice.value='Dashboard saved to MongoDB.';resetLayout();}else{dashboard.value.revision=data.revision;dashboard.value.updatedAt=data.updatedAt;dirty.value=true;notice.value='Dashboard saved. Newer changes are still unsaved.';}}catch(e){error.value=message(e);}finally{saving.value=false;}}
function createDashboard(){newName.value='';dialog.value={kind:'new'};}
async function duplicate(){const copy=clone(dashboard.value);delete copy._id;delete copy.revision;copy.name+=' (copy)';try{const {data}=await api.save(copy);await router.push('/dashboard/'+data._id);}catch(e){error.value=message(e);}}
function exportCurrent(){if(dashboard.value)downloadJson(dashboard.value.charts.map(chartDefinition),'charts.json');}
async function toggleFavorite(item){try{const {data}=await api.get(item._id);data.favorite=!data.favorite;await api.save(data);await load();}catch(e){error.value=message(e);}}
function cancelDialog(){dialog.value=null;if(leaveResolve){leaveResolve(false);leaveResolve=null;}}
async function confirmDialog(){if(saving.value)return;const action=dialog.value;if(!action)return;error.value='';if(action.kind==='remove'){abortQueries();dashboard.value.charts=dashboard.value.charts.filter(c=>String(c.id)!==String(action.chart.id));if(focused.value===String(action.chart.id))focused.value=null;delete results.value[String(action.chart.id)];resetLayout();markDirty();dialog.value=null;refreshData();}else if(action.kind==='discard'){dashboard.value=clone(saved.value);dirty.value=false;editing.value=true;dialog.value=null;abortQueries();resetLayout();refreshData();}else if(action.kind==='leave'){dirty.value=false;dialog.value=null;leaveResolve?.(true);leaveResolve=null;}else{saving.value=true;try{if(action.kind==='delete-dashboard'){await api.remove(action.item);dialog.value=null;await load();}else if(action.kind==='new'){if(!newName.value.trim())return;const {data}=await api.save({name:newName.value,description:'',folder:'General',tags:[],settings:settingsFor({}),charts:[]});dialog.value=null;await router.push('/dashboard/'+data._id);}}catch(e){error.value=message(e);dialog.value=null;}finally{saving.value=false;}}}
function openSettings(){settingsDraft.value=clone(dashboard.value);settingsDraft.value.settings=settingsFor(dashboard.value);tagText.value=dashboard.value.tags.join(', ');intervalText.value=settingsDraft.value.settings.intervals.join(', ');settingsTab.value='General';settingsError.value='';settingsOpen.value=true;}
function applySettings(){const intervals=[...new Set(intervalText.value.split(',').map(s=>s.trim()).filter(Boolean))];if(!settingsDraft.value.name.trim()||!intervals.length||intervals.some(s=>!refreshIntervals.slice(1).includes(s))||(settingsDraft.value.settings.refresh!=='Off'&&!intervals.includes(settingsDraft.value.settings.refresh))){settingsError.value='Enter a name and valid refresh intervals. The default refresh must appear in the list.';return;}settingsDraft.value.tags=tagText.value.split(',').map(s=>s.trim()).filter(Boolean);settingsDraft.value.settings.intervals=intervals;dashboard.value=settingsDraft.value;range.value=dashboard.value.settings.range;refresh.value=dashboard.value.settings.refresh;settingsOpen.value=false;markDirty();}
async function importValue(charts,name){if(!Array.isArray(charts))throw new Error('Expected the original chart JSON array.');const {data}=await api.save({name,folder:'General',description:'Imported chart definitions.',tags:['imported'],settings:settingsFor({}),charts:charts.map(chartDefinition)});await router.push('/dashboard/'+data._id);}
async function importCharts(event){const file=event.target.files[0];try{if(!file)return;if(file.size>1500000)throw new Error('The JSON file is too large.');await importValue(JSON.parse(await file.text()),file.name.replace(/\.json$/i,''));}catch(e){error.value=e.response?.data?.message||e.message;}finally{event.target.value='';}}
function routeGuard(){if(saving.value&&dirty.value)return false;if(!dirty.value)return true;return new Promise(resolve=>{leaveResolve=resolve;dialog.value={kind:'leave'};});}
onBeforeRouteLeave(routeGuard);onBeforeRouteUpdate((to,from)=>to.params.dashboardId===from.params.dashboardId?true:routeGuard());
function beforeUnload(event){if(dirty.value){event.preventDefault();event.returnValue='';}}
watch(()=>route.params.dashboardId,load);
watch(range,()=>{abortQueries();refreshData();});
watch(refresh,()=>{clearInterval(timer);if(refresh.value==='Off')return;const units={s:1000,m:60000,h:3600000},match=refresh.value.match(/^(\d+)(s|m|h)$/);if(match)timer=setInterval(()=>{if(!editor.value&&!inspection.value&&!settingsOpen.value&&!dialog.value&&(!document.hidden||!settingsFor(dashboard.value).pauseHidden))refreshData();},Number(match[1])*units[match[2]]);});
onMounted(()=>{try{localStorage.removeItem('tomatoesDashboard');}catch{/* Browser storage may be unavailable. */}window.addEventListener('beforeunload',beforeUnload);load();});
onBeforeUnmount(()=>{isAlive=false;loadSerial++;abortQueries();clearInterval(timer);window.removeEventListener('beforeunload',beforeUnload);leaveResolve?.(false);});
</script>
